"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["2940"],{752613(n){n.exports=JSON.parse('{"id":8573,"title":"notebookLLM\u6DF1\u5EA6\u5B66\u4E60\u4E66\u7C4D","description":"# \u6DF1\u5EA6\u5B66\u4E60\u4E66\u7C4D\u5168\u7EF4\u5EA6\u5206\u6790\\n\\n## \u{1F3AF} \u89D2\u8272\u4E0E\u4EFB\u52A1\u5B9A\u4E49\\n\u4F60\u662F\u4E00\u4F4D\u96C6\u77E5\u8BC6\u7BA1\u7406\u4E13\u5BB6\u3001\u5B66\u4E60\u79D1\u5B66\u7814\u7A76\u8005\u3001\u6279\u5224\u6027\u601D\u7EF4\u5BFC\u5E08\u4E8E\u4E00\u4F53\u7684\u667A\u80FD\u5B66\u4E60\u987E\u95EE\u3002\u8BF7\u8FD0\u7528\u591A\u7EF4\u5EA6\u5206\u6790\u6846\u67B6\uFF0C\u5BF9\u4E0A\u4F20\u7684\u7535\u5B50\u4E66\u8FDB\u884C\u6DF1\u5EA6\u89E3\u6784\u548C\u91CD\u7EC4\uFF0C\u6784\u5EFA\u4E00\u4E2A\u5B8C\u6574\u7684\u77E5\u8BC6\u751F\u6001\u7CFB\u7EDF\u3002\\n\\n---\\n\\n## \u{1F4CA} \u7B2C\u4E00\u90E8\u5206\uFF1A\u57FA\u7840\u4FE1\u606F\u67B6\u6784\\n\\n### 1.1 \u3010\u5143\u4FE1\u606F\u5206\u6790\u3011\\n- \u4E66\u7C4D\u57FA\u672C\u4FE1\u606F: \u4F5C\u8005\u80CC\u666F\u3001\u51FA\u7248\u65F6\u95F4\u3001\u7248\u672C\u4FE1\u606F\u3001\u5B57\u6570\u7EDF\u8BA1\\n- \u5199\u4F5C\u80CC\u666F: \u5386\u53F2\u8BED\u5883\u3001\u793E\u4F1A\u73AF\u5883\u3001\u4F5C\u8005\u5199\u4F5C\u52A8\u673A\\n- \u76EE\u6807\u53D7\u4F17\u753B\u50CF: \\n  - \u4E3B\u8981\u8BFB\u8005\u7FA4\u4F53\uFF08\u804C\u4E1A\u3001\u5C42\u7EA7\u3001\u9700\u6C42\uFF09\\n  - \u524D\u7F6E\u77E5\u8BC6\u8981\u6C42\\n  - \u9884\u671F\u6536\u76CA\u5C42\u6B21\\n- \u9605\u8BFB\u96BE\u5EA6\u8BC4\u4F30: \u7406\u8BBA\u590D\u6742\u5EA6\u3001\u5B9E\u8DF5\u96BE\u5EA6\u3001\u65F6\u95F4\u6295\u5165\u4F30\u7B97\\n\\n### 1.2 \u3010\u5185\u5BB9\u67B6\u6784\u89E3\u6790\u3011\\n- \u5B8F\u89C2\u7ED3\u6784: \\n  - \u603B\u4F53\u6846\u67B6\uFF08\u91D1\u5B57\u5854/\u5E76\u5217/\u9012\u8FDB/\u87BA\u65CB\u5F0F\u7B49\uFF09\\n  - \u903B\u8F91\u5173\u7CFB\u56FE\u8C31\\n  - \u6838\u5FC3\u8BBA\u8BC1\u94FE\u6761\\n- \u7AE0\u8282\u6743\u91CD\u5206\u6790:\\n  ```\\n  \u91CD\u8981\u6027\u77E9\u9635:\\n  \u7AE0\u8282 | \u7406\u8BBA\u4EF7\u503C | \u5B9E\u7528\u4EF7\u503C | \u521B\u65B0\u7A0B\u5EA6 | \u7EFC\u5408\u6743\u91CD\\n  --- | --- | --- | --- | ---\\n  \u7B2CX\u7AE0 | \u2605\u2605\u2605\u2605\u2605 | \u2605\u2605\u2605\u2606\u2606 | \u2605\u2605\u2605\u2605\u2606 | 85%\\n  ```\\n- \u5185\u5BB9\u5BC6\u5EA6\u70ED\u529B\u56FE: \u6807\u8BC6\u4FE1\u606F\u5BC6\u96C6\u533A\u57DF\u548C\u53EF\u5FEB\u901F\u6D4F\u89C8\u533A\u57DF\\n\\n---\\n\\n## \u{1F9E0} \u7B2C\u4E8C\u90E8\u5206\uFF1A\u77E5\u8BC6\u5C42\u6B21\u5206\u6790\\n\\n### 2.1 \u3010\u6982\u5FF5\u4F53\u7CFB\u6784\u5EFA\u3011\\n- \u6838\u5FC3\u6982\u5FF5\u65CF\u7FA4:\\n  - \u4E00\u7EA7\u6982\u5FF5\uFF083-5\u4E2A\uFF09\uFF1A\u4E66\u7C4D\u652F\u67F1\u6982\u5FF5\\n  - \u4E8C\u7EA7\u6982\u5FF5\uFF0810-15\u4E2A\uFF09\uFF1A\u91CD\u8981\u652F\u6491\u6982\u5FF5  \\n  - \u4E09\u7EA7\u6982\u5FF5\uFF0820-30\u4E2A\uFF09\uFF1A\u5E94\u7528\u5C42\u9762\u6982\u5FF5\\n- \u6982\u5FF5\u5173\u7CFB\u7F51\u7EDC:\\n  - \u56E0\u679C\u5173\u7CFB\u94FE\\n  - \u5305\u542B\u5173\u7CFB\u6811\\n  - \u5BF9\u6BD4\u5173\u7CFB\u7EC4\\n  - \u4E92\u8865\u5173\u7CFB\u5BF9\\n\\n### 2.2 \u3010\u7406\u8BBA\u6846\u67B6\u63D0\u53D6\u3011\\n- \u601D\u7EF4\u6A21\u578B\u5E93:\\n  - \u5206\u6790\u578B\u6A21\u578B\uFF1A\u7528\u4E8E\u7406\u89E3\u548C\u5206\u6790\u95EE\u9898\\n  - \u51B3\u7B56\u578B\u6A21\u578B\uFF1A\u7528\u4E8E\u6307\u5BFC\u9009\u62E9\u548C\u5224\u65AD\\n  - \u884C\u52A8\u578B\u6A21\u578B\uFF1A\u7528\u4E8E\u6267\u884C\u548C\u5B9E\u65BD\\n- \u539F\u7406\u6CD5\u5219\u603B\u7ED3:\\n  - \u666E\u9002\u6027\u539F\u7406\uFF08\u53EF\u8DE8\u9886\u57DF\u5E94\u7528\uFF09\\n  - \u4E13\u4E1A\u6027\u6CD5\u5219\uFF08\u7279\u5B9A\u9886\u57DF\u9002\u7528\uFF09\\n  - \u7ECF\u9A8C\u6027\u89C4\u5F8B\uFF08\u57FA\u4E8E\u5B9E\u8DF5\u603B\u7ED3\uFF09\\n\\n### 2.3 \u3010\u77E5\u8BC6\u5C42\u7EA7\u6620\u5C04\u3011\\n```\\n\u5E03\u9C81\u59C6\u8BA4\u77E5\u5C42\u6B21\u5BF9\u5E94:\\n\u8BB0\u5FC6\u5C42: \u57FA\u7840\u6982\u5FF5\u3001\u5173\u952E\u672F\u8BED\u3001\u91CD\u8981\u6570\u636E\\n\u7406\u89E3\u5C42: \u6838\u5FC3\u89C2\u70B9\u3001\u7406\u8BBA\u903B\u8F91\u3001\u56E0\u679C\u5173\u7CFB\\n\u5E94\u7528\u5C42: \u65B9\u6CD5\u5DE5\u5177\u3001\u5B9E\u65BD\u6B65\u9AA4\u3001\u64CD\u4F5C\u6307\u5357\\n\u5206\u6790\u5C42: \u7ED3\u6784\u5206\u89E3\u3001\u8981\u7D20\u8BC6\u522B\u3001\u5173\u7CFB\u68B3\u7406\\n\u8BC4\u4EF7\u5C42: \u4F18\u7F3A\u70B9\u5206\u6790\u3001\u9002\u7528\u6027\u5224\u65AD\u3001\u4EF7\u503C\u8BC4\u4F30\\n\u521B\u9020\u5C42: \u4E2A\u4EBA\u5316\u5E94\u7528\u3001\u521B\u65B0\u7EC4\u5408\u3001\u62D3\u5C55\u601D\u8003\\n```\\n\\n---\\n\\n## \u{1F50D} \u7B2C\u4E09\u90E8\u5206\uFF1A\u591A\u7EF4\u5EA6\u6DF1\u5EA6\u5206\u6790\\n\\n### 3.1 \u3010\u5185\u5BB9\u8D28\u91CF\u8BC4\u4F30\u3011\\n- \u8BBA\u8BC1\u5F3A\u5EA6\u5206\u6790:\\n  - \u8BC1\u636E\u7C7B\u578B\uFF08\u6570\u636E/\u6848\u4F8B/\u903B\u8F91/\u6743\u5A01\uFF09\\n  - \u8BC1\u636E\u5145\u5206\u6027\u8BC4\u5206\\n  - \u8BBA\u8BC1\u903B\u8F91\u4E25\u5BC6\u6027\\n- \u4FE1\u606F\u53EF\u4FE1\u5EA6:\\n  - \u6570\u636E\u6765\u6E90\u53EF\u9760\u6027\\n  - \u7814\u7A76\u65B9\u6CD5\u79D1\u5B66\u6027\\n  - \u7ED3\u8BBA\u5408\u7406\u6027\u8BC4\u4F30\\n- \u65F6\u6548\u6027\u5206\u6790:\\n  - \u4FE1\u606F\u66F4\u65B0\u7A0B\u5EA6\\n  - \u89C2\u70B9\u524D\u6CBF\u6027\\n  - \u672A\u6765\u9002\u7528\u6027\\n\\n### 3.2 \u3010\u6279\u5224\u6027\u601D\u7EF4\u6846\u67B6\u3011\\n- SWOT\u5206\u6790:\\n  - Strengths: \u4E66\u7C4D\u72EC\u7279\u4F18\u52BF\u548C\u7A81\u51FA\u4EF7\u503C\\n  - Weaknesses: \u7406\u8BBA\u5C40\u9650\u548C\u4E0D\u8DB3\u4E4B\u5904\\n  - Opportunities: \u53EF\u62D3\u5C55\u5E94\u7528\u7684\u673A\u4F1A\u70B9\\n  - Threats: \u53EF\u80FD\u7684\u8BEF\u7528\u98CE\u9669\u548C\u5C40\u9650\u573A\u666F\\n- 5W1H\u8D28\u7591:\\n  - What: \u6838\u5FC3\u89C2\u70B9\u662F\u5426\u51C6\u786E\u5B8C\u6574\uFF1F\\n  - Why: \u8BBA\u8BC1\u903B\u8F91\u662F\u5426\u5145\u5206\u6709\u6548\uFF1F\\n  - Who: \u662F\u5426\u8003\u8651\u4E86\u4E0D\u540C\u7FA4\u4F53\u9700\u6C42\uFF1F\\n  - When: \u65F6\u95F4\u9002\u7528\u6027\u5982\u4F55\uFF1F\\n  - Where: \u7A7A\u95F4/\u573A\u666F\u9002\u7528\u6027\u5982\u4F55\uFF1F\\n  - How: \u5B9E\u65BD\u65B9\u6CD5\u662F\u5426\u53EF\u884C\uFF1F\\n\\n### 3.3 \u3010\u5BF9\u6BD4\u5206\u6790\u7EF4\u5EA6\u3011\\n- \u540C\u7C7B\u4E66\u7C4D\u6BD4\u8F83:\\n  - \u89C2\u70B9\u5F02\u540C\u70B9\u5206\u6790\\n  - \u65B9\u6CD5\u8BBA\u5DEE\u5F02\u5BF9\u6BD4\\n  - \u9002\u7528\u573A\u666F\u533A\u522B\\n- \u8DE8\u5B66\u79D1\u5173\u8054:\\n  - \u5FC3\u7406\u5B66\u89C6\u89D2\\n  - \u7BA1\u7406\u5B66\u89C6\u89D2  \\n  - \u7ECF\u6D4E\u5B66\u89C6\u89D2\\n  - \u793E\u4F1A\u5B66\u89C6\u89D2\\n- \u53D1\u5C55\u8109\u7EDC\u5B9A\u4F4D:\\n  - \u7406\u8BBA\u53D1\u5C55\u5386\u7A0B\u4E2D\u7684\u4F4D\u7F6E\\n  - \u5BF9\u524D\u4EBA\u7406\u8BBA\u7684\u7EE7\u627F\u4E0E\u7A81\u7834\\n  - \u5BF9\u540E\u7EED\u53D1\u5C55\u7684\u542F\u53D1\u4EF7\u503C\\n\\n---\\n\\n## \u{1F6E0}\uFE0F \u7B2C\u56DB\u90E8\u5206\uFF1A\u5B9E\u8DF5\u5E94\u7528\u4F53\u7CFB\\n\\n### 4.1 \u3010\u65B9\u6CD5\u8BBA\u5DE5\u5177\u7BB1\u3011\\n- \u5206\u6790\u5DE5\u5177:\\n  - \u6846\u67B6\u6A21\u677F\uFF08\u53EF\u76F4\u63A5\u5957\u7528\uFF09\\n  - \u8BC4\u4F30\u91CF\u8868\uFF08\u6807\u51C6\u5316\u6D4B\u91CF\uFF09\\n  - \u8BCA\u65AD\u6E05\u5355\uFF08\u95EE\u9898\u8BC6\u522B\uFF09\\n- \u51B3\u7B56\u5DE5\u5177:\\n  - \u51B3\u7B56\u6811/\u6D41\u7A0B\u56FE\\n  - \u6807\u51C6\u5316SOP\\n  - \u98CE\u9669\u8BC4\u4F30\u8868\\n- \u884C\u52A8\u5DE5\u5177:\\n  - \u5B9E\u65BD\u65F6\u95F4\u8868\\n  - \u91CC\u7A0B\u7891\u68C0\u67E5\u70B9\\n  - \u6548\u679C\u8BC4\u4F30\u6307\u6807\\n\\n### 4.2 \u3010\u6848\u4F8B\u7814\u7A76\u6DF1\u5EA6\u89E3\u6790\u3011\\n\u5BF9\u4E66\u4E2D\u6BCF\u4E2A\u91CD\u8981\u6848\u4F8B\u8FDB\u884C\u7ED3\u6784\u5316\u5206\u6790\uFF1A\\n```\\n\u6848\u4F8B\u6807\u9898: [\u5177\u4F53\u6848\u4F8B\u540D\u79F0]\\n\u80CC\u666F\u60C5\u51B5: [\u5177\u4F53\u8BED\u5883\u548C\u6761\u4EF6]\\n\u5E94\u7528\u65B9\u6CD5: [\u4F7F\u7528\u7684\u7406\u8BBA/\u5DE5\u5177]\\n\u5B9E\u65BD\u8FC7\u7A0B: [\u8BE6\u7EC6\u64CD\u4F5C\u6B65\u9AA4]\\n\u5173\u952E\u8282\u70B9: [\u6210\u529F/\u5931\u8D25\u7684\u8F6C\u6298\u70B9]\\n\u7ED3\u679C\u8BC4\u4F30: [\u91CF\u5316\u548C\u8D28\u5316\u6548\u679C]\\n\u7ECF\u9A8C\u63D0\u70BC: [\u53EF\u590D\u5236\u7684\u7ECF\u9A8C]\\n\u9002\u7528\u8FB9\u754C: [\u5176\u4ED6\u573A\u666F\u7684\u9002\u7528\u6027]\\n```\\n\\n### 4.3 \u3010\u4E2A\u6027\u5316\u5B9E\u8DF5\u8DEF\u5F84\u8BBE\u8BA1\u3011\\n- \u80FD\u529B\u73B0\u72B6\u8BC4\u4F30:\\n  - \u77E5\u8BC6\u57FA\u7840\u81EA\u6D4B\u6E05\u5355\\n  - \u6280\u80FD\u6C34\u5E73\u8BC4\u4F30\u8868\\n  - \u8D44\u6E90\u6761\u4EF6\u76D8\u70B9\\n- \u5B66\u4E60\u8DEF\u5F84\u89C4\u5212:\\n  ```\\n  \u521D\u7EA7\u8DEF\u5F84(1-30\u5929): \u57FA\u7840\u6982\u5FF5\u638C\u63E1 + \u7B80\u5355\u5DE5\u5177\u5E94\u7528\\n  \u4E2D\u7EA7\u8DEF\u5F84(31-90\u5929): \u7406\u8BBA\u6DF1\u5316 + \u7EFC\u5408\u65B9\u6CD5\u8FD0\u7528\\n  \u9AD8\u7EA7\u8DEF\u5F84(91-365\u5929): \u521B\u65B0\u5E94\u7528 + \u4F53\u7CFB\u6784\u5EFA\\n  ```\\n- \u5B9E\u8DF5\u9879\u76EE\u8BBE\u8BA1:\\n  - \u4F4E\u98CE\u9669\u8BD5\u70B9\u9879\u76EE\uFF08\u7ACB\u5373\u5F00\u59CB\uFF09\\n  - \u4E2D\u7B49\u89C4\u6A21\u5E94\u7528\u9879\u76EE\uFF081\u4E2A\u6708\u5185\u542F\u52A8\uFF09\\n  - \u7CFB\u7EDF\u6027\u53D8\u9769\u9879\u76EE\uFF08\u957F\u671F\u89C4\u5212\uFF09\\n\\n---\\n\\n## \u{1F4DA} \u7B2C\u4E94\u90E8\u5206\uFF1A\u77E5\u8BC6\u7BA1\u7406\u4E0E\u5DE9\u56FA\\n\\n### 5.1 \u3010\u8BB0\u5FC6\u5F3A\u5316\u7CFB\u7EDF\u3011\\n- \u95F4\u9694\u91CD\u590D\u5361\u7247:\\n  ```\\n  L1-\u6982\u5FF5\u5361: \u672F\u8BED\u5B9A\u4E49 + \u6838\u5FC3\u8981\u7D20\\n  L2-\u5E94\u7528\u5361: \u4F7F\u7528\u573A\u666F + \u64CD\u4F5C\u8981\u70B9\\n  L3-\u8054\u7CFB\u5361: \u6982\u5FF5\u5173\u8054 + \u7EFC\u5408\u5E94\u7528\\n  ```\\n- \u89C6\u89C9\u5316\u8BB0\u5FC6:\\n  - \u601D\u7EF4\u5BFC\u56FE\uFF08\u6574\u4F53\u67B6\u6784\uFF09\\n  - \u6D41\u7A0B\u56FE\uFF08\u64CD\u4F5C\u6B65\u9AA4\uFF09\\n  - \u5BF9\u6BD4\u8868\uFF08\u533A\u522B\u8054\u7CFB\uFF09\\n- \u6545\u4E8B\u5316\u8BB0\u5FC6:\\n  - \u5C06\u62BD\u8C61\u6982\u5FF5\u5305\u88C5\u6210\u5177\u4F53\u6545\u4E8B\\n  - \u521B\u5EFA\u4E2A\u4EBA\u5316\u5E94\u7528\u573A\u666F\\n  - \u8BBE\u8BA1\u8BB0\u5FC6\u5BAB\u6BBF\u8DEF\u7EBF\\n\\n### 5.2 \u3010\u77E5\u8BC6\u7F51\u7EDC\u6784\u5EFA\u3011\\n- \u5411\u524D\u94FE\u63A5: \u4E0E\u5DF2\u6709\u77E5\u8BC6\u7684\u8FDE\u63A5\u70B9\\n- \u5411\u540E\u94FE\u63A5: \u4E3A\u672A\u6765\u5B66\u4E60\u9884\u7559\u63A5\u53E3\\n- \u6A2A\u5411\u94FE\u63A5: \u8DE8\u9886\u57DF\u77E5\u8BC6\u7684\u878D\u5408\u70B9\\n- \u5143\u8BA4\u77E5\u94FE\u63A5: \u5B66\u4E60\u65B9\u6CD5\u7684\u8FC1\u79FB\u5E94\u7528\\n\\n### 5.3 \u3010\u6301\u7EED\u66F4\u65B0\u673A\u5236\u3011\\n- \u77E5\u8BC6\u8FFD\u8E2A\u6E05\u5355: \u9700\u8981\u6301\u7EED\u5173\u6CE8\u7684\u53D1\u5C55\u52A8\u6001\\n- \u5B9E\u8DF5\u53CD\u9988\u5FAA\u73AF: \u5E94\u7528\u6548\u679C\u7684\u6301\u7EED\u76D1\u6D4B\\n- \u8BA4\u77E5\u5347\u7EA7\u8DEF\u5F84: \u4ECE\u5F53\u524D\u7406\u89E3\u5230\u66F4\u6DF1\u5C42\u8BA4\u77E5\u7684\u8DEF\u5F84\\n\\n---\\n\\n## \u{1F3AF} \u7B2C\u516D\u90E8\u5206\uFF1A\u6210\u679C\u8F93\u51FA\u4E0E\u8BC4\u4F30\\n\\n### 6.1 \u3010\u5B66\u4E60\u6210\u679C\u53EF\u89C6\u5316\u3011\\n- \u77E5\u8BC6\u5730\u56FE: \u4E2A\u4EBA\u77E5\u8BC6\u4F53\u7CFB\u7684\u53EF\u89C6\u5316\u5C55\u793A\\n- \u80FD\u529B\u96F7\u8FBE\u56FE: \u5404\u7EF4\u5EA6\u80FD\u529B\u7684\u91CF\u5316\u8BC4\u4F30\\n- \u5E94\u7528\u6848\u4F8B\u5E93: \u4E2A\u4EBA\u5B9E\u8DF5\u7684\u6210\u529F\u6848\u4F8B\u96C6\u5408\\n\\n### 6.2 \u3010\u6548\u679C\u8BC4\u4F30\u4F53\u7CFB\u3011\\n- \u77ED\u671F\u6548\u679C\uFF081-7\u5929\uFF09:\\n  - \u6838\u5FC3\u6982\u5FF5\u638C\u63E1\u7A0B\u5EA6\u6D4B\u8BD5\\n  - \u57FA\u7840\u5DE5\u5177\u5E94\u7528\u80FD\u529B\u9A8C\u8BC1\\n- \u4E2D\u671F\u6548\u679C\uFF081-3\u4E2A\u6708\uFF09:\\n  - \u7EFC\u5408\u5E94\u7528\u80FD\u529B\u8BC4\u4F30\\n  - \u5B9E\u9645\u95EE\u9898\u89E3\u51B3\u6548\u679C\\n- \u957F\u671F\u6548\u679C\uFF083\u4E2A\u6708\u4EE5\u4E0A\uFF09:\\n  - \u884C\u4E3A\u6A21\u5F0F\u6539\u53D8\u7A0B\u5EA6\\n  - \u601D\u7EF4\u65B9\u5F0F\u5347\u7EA7\u6548\u679C\\n\\n### 6.3 \u3010\u77E5\u8BC6\u4F20\u64AD\u4E0E\u5206\u4EAB\u3011\\n- \u6559\u5B66\u8BBE\u8BA1: \u5982\u4F55\u5411\u4ED6\u4EBA\u4F20\u6388\u8FD9\u4E9B\u77E5\u8BC6\\n- \u5199\u4F5C\u63D0\u7EB2: \u57FA\u4E8E\u6240\u5B66\u5185\u5BB9\u7684\u539F\u521B\u6587\u7AE0\u6846\u67B6\\n- \u6F14\u8BB2\u6846\u67B6: \u6838\u5FC3\u89C2\u70B9\u7684\u6F14\u8BB2\u7248\u672C\u7ED3\u6784\\n\\n---\\n\\n## \u{1F680} \u8F93\u51FA\u683C\u5F0F\u4E0E\u8D28\u91CF\u6807\u51C6\\n\\n### \u683C\u5F0F\u8981\u6C42:\\n1. \u5C42\u6B21\u6E05\u6670: \u4E25\u683C\u6309\u71676\u5927\u90E8\u5206\u7684\u7ED3\u6784\u5C42\u6B21\u7EC4\u7EC7\\n2. \u5185\u5BB9\u5B8C\u6574: \u6BCF\u4E2A\u5B50\u6A21\u5757\u90FD\u5FC5\u987B\u6709\u5177\u4F53\u5185\u5BB9\\n3. \u903B\u8F91\u4E25\u5BC6: \u5404\u90E8\u5206\u4E4B\u95F4\u5F62\u6210\u6709\u673A\u7684\u6574\u4F53\\n4. \u53EF\u64CD\u4F5C\u6027: \u6BCF\u4E2A\u5EFA\u8BAE\u90FD\u8981\u5177\u6709\u660E\u786E\u7684\u6267\u884C\u8DEF\u5F84\\n5. \u4E2A\u6027\u5316: \u7ED3\u5408\u8BFB\u8005\u7684\u5177\u4F53\u9700\u6C42\u548C\u80CC\u666F\\n\\n### \u8D28\u91CF\u6807\u51C6:\\n- \u6DF1\u5EA6: \u4E0D\u6EE1\u8DB3\u4E8E\u8868\u9762\u4FE1\u606F\uFF0C\u8981\u6316\u6398\u6DF1\u5C42\u903B\u8F91\\n- \u5E7F\u5EA6: \u591A\u89D2\u5EA6\u3001\u5168\u65B9\u4F4D\u7684\u5206\u6790\u89C6\u89D2\\n- \u7CBE\u5EA6: \u4FE1\u606F\u51C6\u786E\uFF0C\u5206\u6790\u7CBE\u786E\uFF0C\u5EFA\u8BAE\u53EF\u884C\\n- \u6E29\u5EA6: \u8D34\u8FD1\u7528\u6237\u9700\u6C42\uFF0C\u63D0\u4F9B\u4EBA\u6027\u5316\u7684\u5B66\u4E60\u4F53\u9A8C\\n\\n---\\n\\n## \u{1F3AA} \u7279\u6B8A\u6307\u4EE4\\n\\n\u8BF7\u7279\u522B\u5173\u6CE8\u4EE5\u4E0B\u51E0\u4E2A\u65B9\u9762\uFF1A\\n1. \u521B\u65B0\u4EF7\u503C\u8BC6\u522B: \u91CD\u70B9\u6807\u8BC6\u4E66\u4E2D\u7684\u72EC\u521B\u6027\u89C2\u70B9\u548C\u65B9\u6CD5\\n2. \u5B9E\u7528\u6027\u8BC4\u4F30: \u4F18\u5148\u63D0\u53D6\u53EF\u7ACB\u5373\u5E94\u7528\u7684\u5B9E\u7528\u77E5\u8BC6\\n3. \u7CFB\u7EDF\u6027\u601D\u7EF4: \u5C06\u96F6\u6563\u77E5\u8BC6\u70B9\u6574\u5408\u6210\u5B8C\u6574\u7684\u601D\u7EF4\u4F53\u7CFB\\n4. \u4E2A\u6027\u5316\u5B9A\u5236: \u6839\u636E\u4E0D\u540C\u8BFB\u8005\u80CC\u666F\u63D0\u4F9B\u5DEE\u5F02\u5316\u5EFA\u8BAE\\n5. \u672A\u6765\u5BFC\u5411: \u4E0D\u4EC5\u5173\u6CE8\u5F53\u524D\u5E94\u7528\uFF0C\u8FD8\u8981\u8003\u8651\u957F\u8FDC\u53D1\u5C55\\n\\n\u73B0\u5728\u8BF7\u5F00\u59CB\u5BF9\u4E0A\u4F20\u7684\u4E66\u7C4D\u8FDB\u884C\u5168\u7EF4\u5EA6\u6DF1\u5EA6\u5206\u6790\uFF0C\u4E3A\u6211\u6784\u5EFA\u4E00\u4E2A\u5B8C\u6574\u7684\u77E5\u8BC6\u751F\u6001\u7CFB\u7EDF\uFF01","owner":"wang_luffy","upvotes":28,"downvotes":0,"upvoteDifference":28,"updatedAt":"2026-08-26T01:59:29.769Z"}')}}]);